fun filterHabitTemplatesByAddedState(
    templates: List<HabitTemplate>,
    activeHabitNames: Set<String>,
    showAdded: Boolean
): List<HabitTemplate> {
    val activeNames = activeHabitNames.map { it.trim().lowercase() }.toSet()
    return templates.filter { (it.name.trim().lowercase() in activeNames) == showAdded }
}
